hold_stationary_crouch_100hz.code:
def hold_stationary_crouch_100hz(args):
    initial = state()
    if initial['tilt_deg'] > 2.0 or initial['pelvis_pos'][2] < 0.75 or initial['touch_N']['touch_lfoot'] < 20.0 or initial['touch_N']['touch_rfoot'] < 20.0:
        return {'installed': False, 'reason': 'Requires upright double support; not a recovery controller.'}
    base = {j: args['base'][j] for j in robot_joints}
    t0 = initial['t']
    def stationary_support():
        s = state()
        w, x, y, z = s['pelvis_quat']
        pitch = math.asin(np.clip(2 * (w*y - z*x), -1.0, 1.0))
        roll = math.atan2(2 * (w*x + y*z), 1 - 2 * (x*x + y*y))
        u = np.clip((s['t'] - t0) / 1.0, 0.0, 1.0)
        u = u*u*(3 - 2*u)
        targets = {j: base[j] for j in base}
        for side in ('left', 'right'):
            targets[side + '_hip_pitch_joint'] -= 0.18*u
            targets[side + '_knee_joint'] += 0.36*u
            targets[side + '_ankle_pitch_joint'] += -0.18*u + np.clip(0.5*(pitch - 0.025) + 0.1*s['gyro'][1], -0.1, 0.1)
            targets[side + '_ankle_roll_joint'] += np.clip(0.85*roll + 0.15*s['gyro'][0], -0.12, 0.12)
        set_joints(targets)
    set_controller(stationary_support, hz=100)
    wait(1.4)
    return {'installed': True, 'state': state()}
